export default class DecentralizedPubSub {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(event, callback) {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event).push(callback);
  }

  publish(event, data) {
    if (this.subscribers.has(event)) {
      this.subscribers.get(event).forEach(callback => callback(data));
    }
  }

  escalateToMetaAgent(event, data) {
    // Placeholder for escalation logic to meta-agent
    console.log(`Escalating ${event} to meta-agent with data:`, data);
  }
}
